<script setup lang="ts">

type P={id:string;prediction:string;confidence:number;status:string;createdAt:string;signals:any;metadata:any;contentId:string|null;model?:{name:string}|null;modelVersion?:{version:string}|null;content?:{type:string;title:string|null;text:string|null;sourceUrl:string|null;fileName:string|null}|null}; type A={id:string;title:string;status:string;createdAt:string;updatedAt:string;analysisContents:any[];predictions:P[]};

const config=useRuntimeConfig();const api=String(config.public.apiBase||"");const items=ref<A[]>([]);const loading=ref(true);const error=ref("");const id=ref("");

async function load(){loading.value=true;try{const r=await $fetch<{analyses:A[];message?:string}>(`${api}/api/intelligence/graph`,{credentials:"include"});items.value=r.analyses||[];if(!id.value&&items.value.length)id.value=items.value[0]?.id||""}catch(e:any){error.value=e?.data?.message||"Unable to load reports."}finally{loading.value=false}}

await load();function printReport(){if(import.meta.client)window.print()}const report=computed(()=>items.value.find(a=>a.id===id.value));const counts=computed(()=>{const c={TEXT:0,IMAGE:0,SOURCE:0};for(const e of report.value?.analysisContents||[])if(e.type in c)c[e.type as keyof typeof c]++;return c});const analyzedEvidence=computed(()=>{const a=report.value;if(!a)return 0;const completed=new Set(a.predictions.filter(p=>p.status==="COMPLETED").map(p=>p.contentId));return a.analysisContents.filter(e=>completed.has(e.id)).length});const aggregate=computed(()=>{const ps=report.value?.predictions||[];if(!ps.length)return "No aggregated insight: this investigation has no predictions.";const done=ps.filter(p=>p.status==="COMPLETED");if(!done.length)return "Predictions have not completed; no aggregated insight is available.";return `Deterministic summary of ${done.length} completed item prediction(s): ${[...new Set(done.map(p=>p.prediction))].join(", ")}. This is a transparent aggregation of recorded outputs, not an authenticity verdict.`});

function explain(p:P){const s=p.signals||{};const out:string[]=[];if(typeof s.textLength==="number")out.push(`Evidence contains ${s.textLength} characters.`);if(s.hasSourceUrl)out.push("A source URL was provided.");if(s.hasFile)out.push("An image file was provided.");return out.length?out.join(" "):"No additional deterministic signal details were recorded."}

</script>

<template><main class="mx-auto max-w-6xl space-y-6 p-5 sm:p-8"><DashboardNav/><header class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-widest text-[var(--vl-sage-dark)]">Evidence intelligence</p><h1 class="mt-2 text-3xl font-semibold">Investigation reports</h1><p class="mt-2 text-sm text-[var(--vl-muted)]">A print friendly view of saved evidence and deterministic MVP predictions.</p></div><button class="rounded-xl bg-[var(--vl-sage-dark)] px-5 py-3 text-sm font-semibold text-white print:hidden" :disabled="!report" @click="printReport">Print report</button></header><div v-if="loading" class="rounded-2xl bg-white/70 p-8">Loading reports…</div><div v-else-if="error" class="rounded-2xl border border-red-200 p-6">{{error}}</div><div v-else-if="!items.length" class="rounded-2xl border border-dashed p-10 text-center text-[var(--vl-muted)]">No investigation data is available for reports.</div><template v-else><label class="block text-sm font-medium">Investigation<select v-model="id" class="mt-2 block w-full max-w-xl rounded-xl border border-[var(--vl-border)] bg-white p-3"><option v-for="a in items" :key="a.id" :value="a.id">{{a.title}}</option></select></label><article v-if="report" class="space-y-6 rounded-3xl border border-[var(--vl-border)] bg-[#fbfaf6] p-6 sm:p-10"><div class="border-b border-[var(--vl-border)] pb-5"><p class="text-xs uppercase tracking-widest text-[var(--vl-muted)]">VeriLens · Deterministic MVP report</p><h2 class="mt-2 text-3xl font-semibold">{{report.title}}</h2><p class="mt-2 text-sm">Status: {{report.status}} · Created: {{new Date(report.createdAt).toLocaleString()}}</p></div><section class="grid gap-3 sm:grid-cols-5"><div class="rounded-xl bg-white p-4"><p class="text-xs text-[var(--vl-muted)]">Evidence</p><b>{{report.analysisContents.length}}</b></div><div class="rounded-xl bg-white p-4"><p class="text-xs text-[var(--vl-muted)]">Analyzed</p><b>{{analyzedEvidence}}</b></div><div v-for="(n,t) in counts" :key="t" class="rounded-xl bg-white p-4"><p class="text-xs text-[var(--vl-muted)]">{{t}}</p><b>{{n}}</b></div></section><section><h3 class="text-lg font-semibold">Overall verdict</h3><p class="mt-2 rounded-xl bg-white p-4 text-sm leading-6">Not produced. The deterministic MVP engine does not establish content authenticity.</p></section><section><h3 class="text-lg font-semibold">Aggregated insight</h3><p class="mt-2 rounded-xl bg-[#eef0e9] p-4 text-sm leading-6">{{aggregate}}</p></section><section><h3 class="text-lg font-semibold">Evidence and predictions</h3><div v-if="!report.analysisContents.length" class="mt-3 text-sm text-[var(--vl-muted)]">No evidence has been added.</div><div v-for="e in report.analysisContents" :key="e.id" class="mt-3 break-inside-avoid rounded-xl border border-[var(--vl-border)] bg-white p-4"><div class="flex flex-wrap justify-between gap-2"><b>{{e.title||e.type}}</b><span class="text-xs">{{e.type}} · {{new Date(e.createdAt).toLocaleString()}}</span></div><p v-if="e.text" class="mt-2 whitespace-pre-wrap text-sm">{{e.text.slice(0,1200)}}{{e.text.length>1200?'…':''}}</p><a v-if="e.sourceUrl" :href="e.sourceUrl" target="_blank" rel="noopener noreferrer" class="mt-2 block break-all text-sm underline">{{e.sourceUrl}}</a><p v-if="e.fileName" class="mt-2 text-sm">{{e.fileName}}</p><div v-for="p in report.predictions.filter(x=>x.contentId===e.id)" :key="p.id" class="mt-4 border-t border-[var(--vl-border)] pt-3 text-sm"><b>{{p.prediction}}</b> · {{Math.round(p.confidence*100)}}% confidence · {{p.status}}<p class="mt-1 text-[var(--vl-muted)]">{{explain(p)}}</p><p class="mt-1 text-xs text-[var(--vl-muted)]">Engine: {{p.metadata?.engine||'Unspecified'}} v{{p.metadata?.version||'—'}} · {{p.createdAt?new Date(p.metadata?.generatedAt||p.createdAt).toLocaleString():''}}</p></div></div></section></article></template></main></template>



